import numpy as np

def solve(g, verbose=False):
    arr=[list(r) for r in g]; h,w=len(arr),len(arr[0])
    cnt={}
    for r in range(h):
        for c in range(w):
            cnt.setdefault(arr[r][c],0); cnt[arr[r][c]]+=1
    bg=max(cnt,key=lambda v:cnt[v])
    others={v:c for v,c in cnt.items() if v!=bg}
    D=min(others,key=lambda v:others[v])
    Ws={v for v in others if v!=D}
    vals=list(Ws)
    # bar segments: connected components of W cells
    def comps(g,val):
        h,w=len(g),len(g[0]); seen=set(); res=[]
        for r in range(h):
            for c in range(w):
                if g[r][c]==val and (r,c) not in seen:
                    st={(r,c)}; seen.add((r,c)); s=set([st]); q=deque(st)
                    cs=[]
                    while q:
                        a,b=q.popleft(); cs.append((a,b))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
