import numpy as np

def solve(g, verbose=False):
    arr=[list(r) for r in g]; h,w=len(arr),len(arr[0])
    cnt={}
    for r in range(h):
        for c in range(w):
            cnt.setdefault(arr[r][c],0); cnt[arr[r][c]]+=1
    bg=max(cnt,key=lambda v:cnt[v])
    others={v:c for v,c in cnt.items() if v!=bg}
    D=min(others,key=lambda v:others[v])
    Ws={v for v in others if v!=D}
    vals=list(Ws)
    def comps(g,val):
        hh=len(g); ww=len(g[0]); seen=set(); res=[]
        for r in range(hh):
            for c in range(ww):
                if g[r][c]==val and (r,c) not in seen:
                    st=[(r,c)]; q=deque([st]); seen.add((r,c)); cells=[]
                    while q:
                        cur=q.popleft()
                        a,b=cur[-1]
                        cells.append((a,b))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+dx,b+dy
                            if 0<=x<hh and 0<=y<ww and g[x][y]==val and (x,y) not in seen:
                                seen.add((x,y)); q.append(cur+[(x,y)])
                    res.append(cells)
        return res
    bars=comps(arr,vals[0]) if vals else []
    dots=[(r,c) for r in range(h) for c in range(w) if arr[r][c]==D]
    out=[row[:] for row in arr]
    for r0,c0 in dots:
        # nearest bar component by min average distance to its cells
        def score(cells):
            return sum(abs(r0-a)+abs(c0-b) for a,b in cells)/len(cells)
        best=min(bars,key=score)
        horiz=all(a==best[0][0] for a,b in best)
        if not horiz:   # vertical bar -> horizontal ray toward it
            t=min(best,key=lambda p:abs(p[1]-c0))
            if t[1]<c0:
                for c in range(t[1],c0):
                    if out[r0][c]!=bg and out[r0][c]!=D: break
                    out[r0][c]=D
            else:
                for c in range(c0,t[1]+1):
                    if out[r0][c]!=bg and out[r0][c]!=D: break
                    out[r0][c]=D
        else:           # horizontal bar -> vertical ray toward it
            t=min(best,key=lambda p:abs(p[0]-r0))
            if t[0]>r0:
                for rr in range(r0+1,h):
                    if out[rr][c0]!=bg and out[rr][c0]!=D: break
                    out[rr][c0]=D
            else:
                for rr in range(t[0],-1,-1):
                    if out[rr][c0]!=bg and out[rr][c0]!=D: break
                    out[rr][c0]=D
        out[r0][c0]=4
    return out

