    cc=comps(g)
    cnt=collections.Counter(int(v) for v in g.ravel()); bg=cnt.most_common(1)[0][0]
    # find bar components (long straight lines of non-bg, color != marker?) 
    bars=[]; others=[]
    for col,cs in cc:
        ys={p//W for p in cs}; xs={p%W for p in cs}
        if len(ys)>len(xs): h=len(ys); w=len(xs)
        else: h=h=len(xs); w=len(ys)
        big=(h>=4 and w==1) or (w>=4 and h==1)
        if big: bars.append((col,cs))
        elif col!=bg: others.append((col,cs))
    out=np.full_like(g,bg)
    painted=set()
    for col,cs in bars:
        # fill whole bounding box with bar color
        ys_=sorted({p//W for p in cs}); xs_=sorted({p%W for p in cs})
        for y_ in ys_:
            for x_ in xs_:
                pos=y_*W+x_; out[pos]=col
                painted.add(pos)
        # keep bar cells as-is? they're already color col
    for col,cs in others:
        ys_=sorted({p//W for p in cs}); xs_=sorted({p%W for p in cs})
        h=max(ys_)-min(ys_)+1; w=max(xs_)-min(xs_)+1
        r0=ys_[0]; c0=xs_[0]
        for dr in range(h):
            for dc in range(w):
                pos=(r0+dr)*W+(c0+dc)
                if out[pos]!=col:
                    out[pos]=col
                    painted.add(pos)
        for p in cs:
            if int(out[p])!=col:
                out[p]=4
    return out.tolist()
