def run(g):
    g=np.array(g); H,W=g.shape
    cnt=collections.Counter(int(v) for v in g.ravel()); bg=cnt.most_common(1)[0][0]
    src={(y,x) for y in range(H) for x in range(W) if int(g[y][x])!=bg}
    out=np.full_like(g,bg)
    occupied={(y,x) for y in range(H) for x in range(W) if int(g[y][x])!=bg}
    for (y,x) in sorted(src):
        out[y][x]=4
    def shoot(yy,xx,dy,dx):
        yy_,xx_=yy+dy,xx+dx
        while 0<=yy_<H and 0<=xx_<W:
            if (yy_,xx_) in occupied or out[yy_][xx_]!=bg: break
            out[yy_][xx_]=8
            yy_,xx_=yy_+dy,xx_+dx
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)): shoot(y,x,dy,dx)
    return out.tolist()

