    H,W=len(g),len(g[0])
    bg_=Counter(x for r in g for x in r).most_common(1)[0][0]
    res=[row[:] for row in g]; seen=[[False]*W for _ in range(H)]; comps=[]
    for y in range(H):
        for x in range(W):
            if int(g[y][x])!=bg_ and not seen[y][x]:
                c=int(g[y][x]); q=deque([(y,x)]); seen[y][x]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,DB in DIRS:
                        nb=(a+da,b+DB)
                        if 0<=nb[0]<H and 0<=nb[1]<W and not seen[nb[0]][nb[1]] and int(g[nb[0]][nb[1]])==c:
                            seen[nb[0]][nb[1]]=True; q.append(nb)
                comps.append((c,tuple(sorted(cells))))
    mk={(cy,cx) for c,o in comps if len(o)==1}
    mcol={c for (c,o) in comps if len(o)==1}.pop()
    painted=set()
    def reflect(pos, d):
        y,x=pos; dy,dx=d
        while True:
            ny,nx=y+dy,x+dx
            if not (0<=ny<H and 0<=nx<W):
                return (ny%2*2-dy, (-dx)%2*2-dx) # stub
            if abs(ny)>=H or abs(nx)>=W:
                dy,dx=(-dy,-dx)
                break
            if int(res[ny][nx])!=bg_:
                return pos,d
    # Instead implement simple bounce off borders
    def dir_after(p,d):
        y,x=p; dy,dx=d
        while True:
            ny,nx=y+dy,x+dx
            if ny<0: return (-dy,dx)   # top -> down
            if ny>=H: return (-dy,dx)   # bottom -> up
            if nx<0: return (dy,-dx)    # left -> right
            if nx>=W: return (dy,-dx)   # right -> left
            if int(res[ny][nx])!=bg_:
                return p,d
            y,x=ny,nx
    for m in mk:
        for d in [(-1,0),(1,0),(0,-1),(0,1)]:
            painted.add(m)
            y,x=m; dy,dx=d
            while True:
                ny,nx=y+dy,x+dx
                if not(0<=ny<H and 0<=nx<W): return
                if int(res[ny][nx])!=bg_: break
                if int(go[ny][nx])==mcol and go[ny][nx]==res[ny][nx]: break
                res[ny][nx]=mcol; y,x=ny,nx; dy,dx=dir_after((y,x),(dy,dx))
                painted.add((y,x))
    return res, painted

